[[[
  const mass_entity = states['sensor.mass_media_entity'].state;
  const colorThief = new ColorThief();
  const img = new Image();
  const image_url = states[mass_entity].attributes.entity_picture_local;

  function calculateLuminance(r, g, b) {
    // Normalize the RGB values
    const [R, G, B] = [r / 255, g / 255, b / 255];                
    // Adjust the RGB values for luminance calculation
    const adjust = (value) => {
        return (value <= 0.03928) ? value / 12.92 : Math.pow((value + 0.055) / 1.055, 2.4);
    };                
    // Calculate luminance using the formula
    const luminance = 0.2126 * adjust(R) + 0.7152 * adjust(G) + 0.0722 * adjust(B);                
    return luminance;
  }

  function calculateContrastRatio(rgb1, rgb2) {
    const luminance1 = calculateLuminance(rgb1[0], rgb1[1], rgb1[2]);
    const luminance2 = calculateLuminance(rgb2[0], rgb2[1], rgb2[2]);

    // Ensure luminance1 is the lighter color
    const lighter = Math.max(luminance1, luminance2);
    const darker = Math.min(luminance1, luminance2);

    // Calculate and return the contrast ratio
    return (lighter + 0.05) / (darker + 0.05);
  }

  function adjustBrightness(color, factor) {
      return color.map(value => {
          let newValue = value * factor;
          return Math.min(255, Math.max(0, Math.round(newValue)));  // Ensure values stay in [0, 255]
      });
  }

  function findLightestAndDarkestColors(rgbArray) {
    if (rgbArray.length === 0) return { lightest: null, darkest: null };                  
    let lightestColor = rgbArray[0];
    let darkestColor = rgbArray[0];
    let maxLuminance = calculateLuminance(...lightestColor);
    let minLuminance = calculateLuminance(...darkestColor);                  
    // Iterate over all colors in the array
    rgbArray.forEach(color => {
        const luminance = calculateLuminance(...color);                  
        if (luminance > maxLuminance) {
            maxLuminance = luminance;
            lightestColor = color;
        }                  
        if (luminance < minLuminance) {
            minLuminance = luminance;
            darkestColor = color;
        }
    });                  
    return [lightestColor, darkestColor];
  }

  function adjustTextColorToMeetContrast(dominantColor, textColor, isLightText) {
    const minimumContrastRatio = 4.5;
    let contrastRatio = calculateContrastRatio(dominantColor, textColor);                  
    // Start with an adjustment factor (increase or decrease brightness)
    let factor = isLightText ? 1.05 : 0.95;  // Light text should be lightened, dark text should be darkened                  
    // Adjust the text color until the contrast ratio is at least 4.5
    while (contrastRatio < minimumContrastRatio) {
        textColor = adjustBrightness(textColor, factor);
        contrastRatio = calculateContrastRatio(dominantColor, textColor);

        // Prevent infinite loops in case it can't reach 4.5 (e.g., very similar colors)
        if (textColor[0] === 255 || textColor[0] === 0) break;  // Fully white or fully black, no more adjustment possible
    }                  
    return `rgb(${textColor.join(', ')})`;
  }

  function adjustTextColorForContrastWithAdjustment(dominantColor, lightTextColor, darkTextColor) {
    const minimumContrastRatio = 4.5;                  
    // Calculate initial contrast ratios
    const contrastWithLight = calculateContrastRatio(dominantColor, lightTextColor);
    const contrastWithDark = calculateContrastRatio(dominantColor, darkTextColor);                  
    // If either color meets the minimum contrast ratio, choose it
    if (contrastWithLight >= minimumContrastRatio) {
        return `rgb(${lightTextColor.join(', ')})`;  // Light color already meets contrast
    } else if (contrastWithDark >= minimumContrastRatio) {
        return `rgb(${darkTextColor.join(', ')})`;  // Dark color already meets contrast
    }                  
    // If neither meets contrast, adjust the closest one
    const isLightText = contrastWithLight > contrastWithDark;
    const closestTextColor = isLightText ? lightTextColor : darkTextColor;                  
    // Adjust the chosen text color to meet the contrast ratio
    return adjustTextColorToMeetContrast(dominantColor, closestTextColor, isLightText);
  }

  // wait 0ms for shadow dom
  setTimeout(() => {                    
    let button_card = this;
    img.addEventListener('load', function() {
      let dominantColor = colorThief.getColor(img);
      console.log(dominantColor);
      let colorPalette = colorThief.getPalette(img, 8);
      let [lightestColor, darkestColor] = findLightestAndDarkestColors(colorPalette);
      let color = adjustTextColorForContrastWithAdjustment(dominantColor, lightestColor, darkestColor);
      let label = button_card.shadowRoot.getElementById("label");
      label.style.color = color;
      document.body.style.background = `rgb(${dominantColor.join(', ')})`;
    });                  
    img.src = image_url;
  }, 0);
]]]
